'use strict';
(()=>{let ar=false,token=0,pages=[],busy=false;const L=(a,b)=>ar?b:a,post=data=>parent.postMessage({...data,token},'*');
 async function load(bytes){const zip=await JSZip.loadAsync(bytes);if(!zip.file('word/document.xml'))throw Error(L('The file is not a supported DOCX document.','الملف ليس مستند DOCX مدعوماً.'));const entries=Object.values(zip.files);if(entries.length>3000||entries.reduce((sum,e)=>sum+(e._data?.uncompressedSize||0),0)>100*1048576)throw Error(L('This DOCX exceeds the safe expanded-size limit.','يتجاوز DOCX الحد المسموح للحجم بعد فك الضغط.'));
 const target=document.getElementById('document'),styles=document.getElementById('document-styles');target.replaceChildren();styles.replaceChildren();
 await docx.renderAsync(bytes,target,styles,{className:'docx',inWrapper:true,ignoreWidth:false,ignoreHeight:false,ignoreFonts:true,breakPages:true,renderHeaders:true,renderFooters:true,renderFootnotes:true,renderEndnotes:true,renderComments:false,renderChanges:false,renderAltChunks:false,useBase64URL:true,experimental:false});
 target.querySelectorAll('a').forEach(a=>{a.removeAttribute('href');a.removeAttribute('target')});target.querySelectorAll('script,iframe,object,embed,form,input').forEach(e=>e.remove());await document.fonts.ready;await Promise.all([...target.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));
 pages=[...target.querySelectorAll('.docx-wrapper>section.docx')];if(!pages.length)throw Error(L('This document contains no renderable pages.','لا يحتوي المستند على صفحات قابلة للعرض.'));if(pages.length>30||pages.some(p=>p.scrollWidth*p.scrollHeight>12000000||p.scrollHeight>16000))throw Error(L('Document is too large to convert safely. Limit: 30 rendered pages.','المستند أكبر من حد التحويل الآمن. الحد: 30 صفحة معروضة.'));post({kind:'loaded',pages:pages.length})}
 async function rasterPage(element){
 const w=Math.ceil(element.getBoundingClientRect().width),h=Math.ceil(Math.max(element.getBoundingClientRect().height,element.scrollHeight));
 const wrapper=document.createElement('div');wrapper.setAttribute('xmlns','http://www.w3.org/1999/xhtml');wrapper.className='docx-wrapper';wrapper.style.cssText='margin:0;padding:0;background:white;width:'+w+'px;height:'+h+'px;';
 const style=document.createElement('style');style.textContent=[...document.querySelectorAll('#document-styles style,#document style')].map(s=>s.textContent).join('\n')+'\n.docx-wrapper>section.docx{margin:0!important;box-shadow:none!important;}';wrapper.append(style);const clone=element.cloneNode(true);clone.style.margin='0';clone.style.boxShadow='none';const computed=getComputedStyle(element);for(const key of ['fontFamily','fontSize','lineHeight','color','direction'])clone.style[key]=computed[key];wrapper.append(clone);
 const html=new XMLSerializer().serializeToString(wrapper),svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'"><foreignObject width="100%" height="100%">'+html+'</foreignObject></svg>';
 const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);await image.decode();const canvas=document.createElement('canvas');canvas.width=Math.ceil(w*1.5);canvas.height=Math.ceil(h*1.5);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas;
 }
 async function exportPDF(){if(!pages.length)throw Error(L('Load a document first.','حمّل المستند أولاً.'));const out=await PDFLib.PDFDocument.create();document.body.classList.add('exporting');try{for(let i=0;i<pages.length;i++){post({kind:'progress',page:i+1,pages:pages.length});const element=pages[i],canvas=await rasterPage(element);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.95));if(!blob)throw Error(L('Unable to encode this page.','تعذر إنشاء صورة الصفحة.'));const image=await out.embedJpg(await blob.arrayBuffer());const w=canvas.width/1.5*.75,h=canvas.height/1.5*.75;out.addPage([w,h]).drawImage(image,{x:0,y:0,width:w,height:h});canvas.width=canvas.height=0}const bytes=await out.save();parent.postMessage({kind:'pdf',token,bytes:bytes.buffer},'*',[bytes.buffer])}finally{document.body.classList.remove('exporting')}}
 window.addEventListener('message',async e=>{if(e.source!==parent)return;const m=e.data;if(m?.kind==='ping'){post({kind:'ready'});return}if(busy||!['load','export'].includes(m?.kind))return;busy=true;token=m.token;ar=!!m.ar||ar;try{if(m.kind==='load'){pages=[];await load(m.bytes)}else await exportPDF()}catch(error){console.error('DOCX conversion failed:',error);pages=[];post({kind:'error',message:L('Could not convert this document. Try a simpler, unprotected DOCX file. ','تعذر تحويل المستند. جرّب ملف DOCX أبسط وغير محمي. ')+(error.message?.startsWith('This ')||error.message?.startsWith('Document ')?error.message:'')})}finally{busy=false}});post({kind:'ready'});
})();
